fn node(lid: &str) -> PreparedWrite {
    PreparedWrite::Node { kind: "note".into(), body: format!("body {lid}"), source_id: SourceId::new("test:s50").unwrap(),
        logical_id: Some(lid.into()), state: fathomdb_engine::InitialState::Active, reason: None, valid_from: None, valid_until: None }
}

#[test]
fn s50_refused_probe() {
    let dir = TempDir::new().expect("tempdir");
    let path = db_path(&dir, "refused_embedder");
    Engine::open(&path).expect("create profile").engine.close().expect("close profile setup");
    let identity = stored_default_identity(&path);
    {
        let opened = Engine::open_with_embedder_for_test(&path, Arc::new(ControlledEmbedder::faithful(identity.clone()))).unwrap();
        opened.engine.configure_vector_kind_for_test("doc").unwrap();
        opened.engine.close().unwrap();
    }
    {
        let opened = Engine::open_with_embedder_for_test(&path, Arc::new(ControlledEmbedder::faithful(identity.clone()))).unwrap();
        assert!(!opened.report.dense_disabled);
        opened.engine.close().unwrap();
    }
    make_probe_verdict_stale(&path);
    {
        let opened = Engine::open(&path).unwrap();
        opened.engine.write(&[body_edge(), node("n1")]).unwrap();
        opened.engine.close().unwrap();
    }
    let opened = Engine::open_with_embedder_for_test(&path, Arc::new(ControlledEmbedder::divergent(identity))).unwrap();
    assert!(opened.report.dense_disabled);
    let r = opened.engine.read_embedding_readiness().unwrap();
    println!("readiness state={:?} pending={} usable={}", r.state, r.pending_count, r.usable_embedder);
    let t = Instant::now();
    let res = opened.engine.drain(3_000);
    println!("drain(3000) -> {:?} in {:?}", res.map_err(|e| format!("{e:?}")), t.elapsed());
    let t = Instant::now();
    let res = opened.engine.transition("n1", fathomdb_engine::LifecycleState::Deleted, None);
    println!("transition(n1, Deleted) -> {:?} in {:?}", res.map_err(|e| format!("{e:?}")), t.elapsed());
}
